1	/**
2	 * 赛狐 Temu 在售集合 diff → 下架 / 上架
3	 * 在售定义：selectStatus === "12"（已加入站点）
4	 *
5	 * 2026-07-31 防误报（服务器实锤）：
6	 * 某轮 getParentPageList 漏拉（unique 954→918），HomeCove 在售被算成 10，
7	 * 飞书误报「下架 5」；下一轮拉全又「上架 5」。半降护栏(50%)挡不住 15→10。
8	 *
9	 * 规则：
10	 *  1) 本店 allMap 相对上轮 allCount 掉太多 → 整轮 skip（接口不全）
11	 *  2) 「下架」必须：已在**确认基准** onSaleMap 中，且本轮仍出现在 allMap、status ≠ 12
12	 *     完全从本轮结果消失的 SKC = 漏数，不告警、不从基准剔除
13	 *  3) 「上架」二次确认（2026-08-05）：
14	 *     - 本轮新出现的 12 → 只进 pendingOnshelf，**不进确认基准、不告警**
15	 *     - 上轮 pending 且本轮仍为 12 → 确认上架告警，写入基准
16	 *     - 上轮 pending 但本轮已不是 12 → 抖动丢弃（不告警上架、更不会假下架）
17	 *  4) 文案：from/to 只写一次合计；注明以赛狐为准，可能与后台「在售中」有延迟
18	 */
19	import { SELECT_STATUS } from './products.js';
20	
21	/**
22	 * @param {object|null} prevSnap { onSaleMap, allCount, statusCounts, pendingOnshelf, ts }
23	 * @param {{ onSaleMap: object, allMap?: object, statusCounts?: object, pullUnique?: number, prevPullUnique?: number }} curr
24	 */
25	export function diffOnSale(prevSnap, curr) {
26	  const prevMap = (prevSnap && prevSnap.onSaleMap) || null;
27	  const currMap = curr.onSaleMap || {};
28	  const allMap = curr.allMap || {};
29	  const currIds = Object.keys(currMap);
30	  const prevPending = (prevSnap && prevSnap.pendingOnshelf) || {};
31	  const events = [];
32	  let skipUpdate = false;
33	
34	  const prevAllCount =
35	    typeof prevSnap?.allCount === 'number'
36	      ? prevSnap.allCount
37	      : null;
38	  const currAllCount = Object.keys(allMap).length;
39	
40	  // —— 全店商品数骤降：赛狐分页/限流漏数（实锤 954→918 级）——
41	  if (prevAllCount != null && prevAllCount >= 30 && currAllCount > 0) {
42	    if (currAllCount < Math.floor(prevAllCount * 0.92)) {
43	      skipUpdate = true;
44	      events.push({
45	        type: 'scan_incomplete',
46	        severity: 'warn',
47	        message: `本店商品列表疑似不全：上轮 all=${prevAllCount} → 本轮 ${currAllCount}，跳过上下架`,
48	      });
49	    }
50	  }
51	
52	  // —— 全局 unique 骤降（monitor 传入）——
53	  if (
54	    !skipUpdate &&
55	    typeof curr.prevPullUnique === 'number' &&
56	    typeof curr.pullUnique === 'number' &&
57	    curr.prevPullUnique >= 100 &&
58	    curr.pullUnique < Math.floor(curr.prevPullUnique * 0.95)
59	  ) {
60	    skipUpdate = true;
61	    events.push({
62	      type: 'scan_incomplete',
63	      severity: 'warn',
64	      message: `全量 unique 疑似不全：${curr.prevPullUnique} → ${curr.pullUnique}，跳过上下架`,
65	    });
66	  }
67	
68	  // —— 在售腰斩（旧护栏，保留；按确认基准）——
69	  if (!skipUpdate && prevMap) {
70	    const prevN = Object.keys(prevMap).length;
71	    // 用「确认基准 ∩ 本轮仍在售」粗估，避免 pending 未入基准时误伤
72	    const stillCommitted = prevMap
73	      ? Object.keys(prevMap).filter((id) => id in currMap).length
74	      : 0;
75	    if (prevN >= 5 && stillCommitted < Math.floor(prevN * 0.5)) {
76	      skipUpdate = true;
77	      events.push({
78	        type: 'scan_incomplete',
79	        severity: 'warn',
80	        message: `在售疑似不全：基准 ${prevN} → 本轮仍在售 ${stillCommitted}，跳过上下架判定`,
81	      });
82	    }
83	  }
84	
85	  let delisted = [];
86	  let listed = []; // 连续两轮确认后的上架
87	  let ghosts = []; // 确认基准内、本轮 allMap 都没有 → 漏数
88	  let nextPending = {};
89	  let listedRawCount = 0;
90	
91	  if (prevMap && !skipUpdate) {
92	    const prevIds = Object.keys(prevMap);
93	
94	    // —— 下架：只从确认基准判定 ——
95	    for (const id of prevIds) {
96	      if (id in currMap) continue; // 仍在售
97	      const row = allMap[id];
98	      if (row && String(row.selectStatus) !== SELECT_STATUS.ON_SALE) {
99	        delisted.push(id);
100	      } else if (!row) {
101	        ghosts.push(id);
102	      } else {
103	        ghosts.push(id);
104	      }
105	    }
106	
107	    // 大量 ghost = 本轮漏拉，整轮作废
108	    if (
109	      ghosts.length >= 3 ||
110	      (prevIds.length >= 5 &&
111	        ghosts.length >= 2 &&
112	        ghosts.length >= Math.ceil(prevIds.length * 0.15))
113	    ) {
114	      skipUpdate = true;
115	      delisted = [];
116	      events.push({
117	        type: 'scan_incomplete',
118	        severity: 'warn',
119	        message: `在售商品本轮失踪 ${ghosts.length} 个（未在结果中出现，疑似接口漏数），跳过上下架；样例 SKC ${ghosts.slice(0, 5).join(',')}`,
120	      });
121	    } else if (ghosts.length) {
122	      events.push({
123	        type: 'scan_ghost',
124	        severity: 'warn',
125	        message: `在售商品本轮未出现 ${ghosts.length} 个（保留基准、不报下架）：${ghosts.slice(0, 8).join(',')}`,
126	        items: ghosts.map((id) => ({
127	          skcId: id,
128	          parentId: prevMap[id]?.parentId || '',
129	          name: prevMap[id]?.name || '',
130	        })),
131	      });
132	    }
133	
134	    if (!skipUpdate) {
135	      // —— 上架二次确认 ——
136	      // 1) 上轮 pending 且本轮仍 12 → 确认
137	      for (const id of Object.keys(prevPending)) {
138	        if (id in currMap) {
139	          listed.push(id);
140	        }
141	        // else: 抖动，丢弃
142	      }
143	
144	      // 2) 本轮 12 且不在确认基准、也不是刚确认的 → 新 pending
145	      //    （刚确认的 listed 本轮直接进基准，不再回 pending）
146	      const listedSet = new Set(listed);
147	      for (const id of currIds) {
148	        if (id in prevMap) continue; // 已在确认基准
149	        if (listedSet.has(id)) continue; // 本轮刚确认
150	        const row = currMap[id];
151	        if (!row) continue;
152	        listedRawCount++;
153	        nextPending[id] = {
154	          skcId: row.skcId || id,
155	          parentId: row.parentId || '',
156	          name: row.name || '',
157	          selectStatus: row.selectStatus || SELECT_STATUS.ON_SALE,
158	          firstSeenTs: prevPending[id]?.firstSeenTs || Date.now(),
159	        };
160	      }
161	
162	      if (Object.keys(nextPending).length) {
163	        events.push({
164	          type: 'onshelf_pending',
165	          severity: 'info',
166	          message: `新进在售 ${Object.keys(nextPending).length} 个，待下轮确认后再告警：${Object.keys(nextPending).slice(0, 8).join(',')}`,
167	          items: Object.values(nextPending),
168	        });
169	      }
170	    }
171	
172	    // 确认基准规模：上轮确认 − 下架 − ghost不扣(carry) + 本轮确认上架
173	    // from/to 用「本轮结束后的确认基准」表达，避免和 pending 混淆
174	    const fromN = prevIds.length;
175	    // to 先按公式，最终与 nextOnSaleMap 对齐（下面构建后回填）
176	    let toN = fromN - delisted.length + listed.length;
177	    // ghost 仍留在基准里，不减少 to
178	
179	    if (!skipUpdate && delisted.length) {
180	      events.push({
181	        type: 'delist',
182	        severity: 'alert',
183	        items: delisted.map((id) => ({
184	          skcId: id,
185	          parentId: (allMap[id] || prevMap[id])?.parentId || '',
186	          name: (allMap[id] || prevMap[id])?.name || '',
187	          selectStatus: allMap[id]?.selectStatus || prevMap[id]?.selectStatus || '',
188	        })),
189	        from: fromN,
190	        to: toN,
191	      });
192	    }
193	    if (!skipUpdate && listed.length) {
194	      events.push({
195	        type: 'onshelf',
196	        severity: 'alert',
197	        items: listed.map((id) => {
198	          const row = currMap[id] || prevPending[id] || {};
199	          return {
200	            skcId: id,
201	            parentId: row.parentId || '',
202	            name: row.name || '',
203	            selectStatus: row.selectStatus || SELECT_STATUS.ON_SALE,
204	          };
205	        }),
206	        from: fromN,
207	        to: toN,
208	      });
209	    }
210	  }
211	
212	  const isFirst = !prevMap;
213	
214	  // —— 构建下一轮确认基准 onSaleMap ——
215	  //  skip → 整表沿用 prev + 保留 pending
216	  //  否则：
217	  //    保留：上轮确认且本轮仍 12
218	  //    保留：ghost（漏数 carry）
219	  //    加入：本轮确认上架 listed
220	  //    不加入：nextPending（待确认）
221	  let nextOnSaleMap;
222	  let nextPendingFinal = nextPending;
223	  if (skipUpdate && prevMap) {
224	    nextOnSaleMap = prevMap;
225	    nextPendingFinal = prevPending;
226	  } else if (!prevMap) {
227	    // 首轮：整表建确认基准，无 pending、不告警
228	    nextOnSaleMap = currMap;
229	    nextPendingFinal = {};
230	  } else {
231	    nextOnSaleMap = {};
232	    for (const id of Object.keys(prevMap)) {
233	      if (delisted.includes(id)) continue;
234	      if (id in currMap) {
235	        nextOnSaleMap[id] = currMap[id];
236	      } else if (ghosts.includes(id)) {
237	        nextOnSaleMap[id] = prevMap[id];
238	      }
239	    }
240	    for (const id of listed) {
241	      if (currMap[id]) nextOnSaleMap[id] = currMap[id];
242	    }
243	  }
244	
