1	/**
2	 * 赛狐开放平台客户端（对齐 sellfox-bridge/bridge/clients/sellfox.py）
3	 * - GET /api/oauth/v2/token.json
4	 * - 业务 POST：query 带 access_token/client_id/timestamp/nonce/sign
5	 * - 签名：HMAC-SHA256(client_secret, 字典序 k=v 用 & 拼接)；body 不参与签名
6	 */
7	import crypto from 'node:crypto';
8	import { log } from '../logger.js';
9	
10	export class SellfoxError extends Error {
11	  constructor(code, msg, requestId) {
12	    super(`sellfox code=${code} msg=${msg}${requestId ? ` requestId=${requestId}` : ''}`);
13	    this.code = code;
14	    this.msg = msg;
15	    this.requestId = requestId;
16	  }
17	}
18	
19	/**
20	 * @param {{ baseUrl?: string, clientId: string, clientSecret: string, timeoutMs?: number, debug?: boolean }} opts
