  const name = (msg.store || '').trim();
  const url = (msg.url || '').trim();
  const cfg = await getConfig();
  const productUrls = Object.assign({}, cfg.productUrls || {});
  if (productUrls[name]) {
    productUrls[name] = productUrls[name].filter((u) => u !== url);
