  const { store, url } = msg;
  if (!url) { sendResponse({ ok: false, msg: 'URL 不能为空' }); return; }
  log.info('FrontCheck manual: store=' + store + ' url=' + url);
  let tab = null;
  try {
    const tabs = await chrome.tabs.query({ url: 'https://www.temu.com/*' });
    tab = tabs.find((t) => {
      return ((t.url || '').split('?')[0]) === ((url || '').split('?')[0]);
